local BLOCKED = { ["SecurityCheck"] = true, ["AntiCheat"] = true, ["BanEvent"] = true, ["Telemetry"] = true }
local oldFire
oldFire = hookfunction(Instance.new("RemoteEvent").FireServer, newcclosure(function(self, ...)
    if BLOCKED[self.Name] and not checkcaller() then
        return
    end
    return oldFire(self, ...)
end))
